from collections import defaultdict
def transform(grid):
    h=len(grid); w=len(grid[0]); d=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,8): d[grid[r][c]].append((r,c))
    if not d: return [[0]*w for _ in range(h)]
    m=min(min(r for r,c in v) for v in d.values())
    cand=[k for k,v in d.items() if min(r for r,c in v)==m]
    tc=min(cand,key=lambda k:max(r for r,c in d[k]))
    cut=max(r for r,c in d[tc])
    for k,v in d.items():
        if any(r==cut for r,c in v):
            cut=max(cut,max(r for r,c in v))
    return [[grid[r][c] if grid[r][c]==8 and r>cut else 0 for c in range(w)] for r in range(h)]
